style.content:
/* General page styling */
body{
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  background-color: #f4f4f4;
}

/* Header styling */
header{
  background-color: #0a4fa3;
  color: white;
  text-align: center;
  padding: 20px;
}

/* Section styling */
section{
  background-color: white;
  margin: 20px;
  padding: 20px;
  border-radius: 8px;
}

/* Section headings */
h2{
  color: #0a4fa3;
}

/* List styling */
ul{
  padding-left: 20px;
}

/* Footer styling */
footer{
  background-color: #222;
  color: white;
  text-align: center;
  padding: 15px;
}

script.content:
// Welcome message
function welcomeMessage() {
  alert("Welcome to Appstine Tech! We make technology easier for you.");
}

// Show message when the page loads
window.onload = welcomeMessage;


// Button action example
function contactMessage() {
  alert("Thank you for contacting Appstine Tech. We will get back to you soon.");
}
